import pytest

from retry import retry


def _flaky(exc, fail_times):
    state = {"n": 0}

    def f():
        state["n"] += 1
        if state["n"] <= fail_times:
            raise exc()
        return "ok"

    return f, state


def test_req_timeout_is_retried_by_default():
    f, state = _flaky(TimeoutError, 2)
    assert retry(times=3)(f)() == "ok" and state["n"] == 3


def test_reg_connection_error_still_retried():
    f, state = _flaky(ConnectionError, 1)
    assert retry(times=3)(f)() == "ok" and state["n"] == 2


def test_reg_other_errors_not_retried():
    f, state = _flaky(ValueError, 1)
    with pytest.raises(ValueError):
        retry(times=3)(f)()
    assert state["n"] == 1


def test_reg_explicit_exceptions_override():
    f, state = _flaky(TimeoutError, 1)
    with pytest.raises(TimeoutError):
        retry(times=3, exceptions=(KeyError,))(f)()
    assert state["n"] == 1

